    return '<div class="a-page">' + head(isNew ? "New obligation" : "Deliver brand guidelines", isNew ? "Record something a party must do under a contract." : "CTR-2026-0014 Acme MSA · §4.2 · due Nov 28", btn("Cancel") + (isNew ? "" : btn("Mark fulfilled", "check") + btn("Waive", "x")) + btn(isNew ? "Create obligation" : "Save", "check", "primary")) +
      '<div class="dc-split r"><div class="stack">' + cd("<b>What must happen</b>", f("Title", val(isNew ? "" : "Deliver brand guidelines")) + g3(f("Type", sel("DELIVERABLE")), f("Status", sel(isNew ? "OPEN" : "IN_PROGRESS")), f("Contract", sel("CTR-2026-0014 Acme MSA", "pen"))) + f("Description", area(isNew ? "" : "Final brand guidelines PDF and source files delivered to the customer's shared folder.", 80)) + g2(f("Source section", sel("§4.2 Deliverables", "pin"), "ContractSection pointer for traceability"), f("Project", sel("Acme Rebrand Website", "folder")))) +
      cd("<b>Who and when</b>", g2(f("Responsible party", sel("Logiqdev Ltd")), f("Responsible member", sel("Anna Meyer", "users"))) + g3(f("Due date", val("Nov 28, 2026")), f("Frequency", sel("Once")), f("Remind before", val("7 days"))) + '<div class="rowx" style="padding-left:0"><div class="grow"><b>Create a task in Tasks (06)</b><small>Stores task_id; execution, time and comments live on the task</small></div>' + sw(isNew ? 1 : 0) + "</div>") + "</div>" +
      '<div class="stack">' + cd("<b>Task</b>", isNew ? '<div class="sub-note">A task will be created in the team of the responsible member.</div>' : '<div class="rowx"><div class="grow"><b>WEB-142</b><small>Rebuild pricing page hero · in progress · Marco Silva</small></div>' + btn("Open", "", "sm") + "</div>", 1) + cd("<b>Origin</b>", kv("Created by", isNew ? "you" : "Anna Meyer · Oct 31") + kv("AI extracted", isNew ? "No" : "No") + kv("Review state", isNew ? "—" : "—"), 0) + cd("<b>History</b>", '<div class="tl"><div class="ev"><b>Status IN_PROGRESS</b><small>Nov 5 · Anna Meyer</small></div><div class="ev"><b>Created</b><small>Oct 31</small></div></div>') + "</div></div>" +
      dm(["ContractObligation · type, status, title, description, due_date, frequency, responsible_party_id, responsible_membership_id, section_id, project_id, task_id, reminder_days_before, fulfilled_at, is_ai_extracted, review_state", "ContractSection · Project (05) · Task (06)"], []) + "</div>";
