      bulkBar(2, sel("Assign owner…", "users") + sel("Reminder windows…", "bell") + btn("Start renewals", "reply", "sm")) +
      ctable(["Contract", "Customer", "Renewal", "Notice deadline", "Time left", "Ends", ">Value", "Owner", ""], R.map((r) => [ink(r[0]), r[1], E(r[2]), r[3], '<span class="badge ' + (parseInt(r[4]) < 30 ? "red" : parseInt(r[4]) < 90 ? "yellow" : "") + '">' + r[4] + "</span>", r[5], r[6] ? '<span class="money">' + eur(r[6]) + "</span>" : "—", av(r[7]), '<button class="btn sm" onclick="event.stopPropagation();location.hash=\'#contracts/renew\'">' + I("reply", 14) + " Renew</button>" + more]), 2) + pager("1–5 of 5") +
      dm(["Contract · renewal_type, renewal_term_months, notice_days, notice_deadline, end_date, expiration_date, status, total_value, owner_membership_id", "ContractType · reminder_windows_days"], []) + "</div>";
